script:
ALLOWED_TRANSITIONS = {
    "C0":          {"C1", "C2", "C6", "C7", "Archived", "Cold"},
    "C1":          {"C2", "C6", "C7"},
    "C2":          {"C2-Q", "C3", "C6", "C7"},
    "C2-Q":        {"C3", "C6", "C7"},
    "C3":          {"C4", "C5", "C8", "C6"},
    "C4":          {"C5", "C8"},
    "C5":          {"C8"},
    "C6":          set(),
    "C7":          {"C6", "C8"},
    "C8":          set(),
    "Cold":        {"C0", "Reactivated"},
    "Reactivated": {"C0", "C1", "C2", "C6", "Archived"},
    "Archived":    set(),
}

if not doc.is_new():
    old_doc = doc.get_doc_before_save()
    old_status = old_doc.status if old_doc else None
    new_status = doc.status
    if old_status and old_status != new_status:
        is_privileged = frappe.has_role("Administrator") or frappe.has_role("Sales Head")
        if not is_privileged:
            if frappe.has_role("B2F Team"):
                if old_status != "C7" or new_status not in ("C6", "C8"):
                    frappe.throw("B2F Team can only update C7 leads to C6 or C8")
            elif frappe.has_role("Jr. Sales Executive"):
                if new_status not in ("C1", "C2", "C6"):
                    frappe.throw("Spotters can only move leads to C1, C2, or C6")
            elif frappe.has_role("Calling Team"):
                if old_status not in ("C0", "Cold", "Reactivated"):
                    frappe.throw("Calling Team can only manage leads at C0/Cold/Reactivated")
                if new_status not in ("C1", "C2", "C6", "C7", "Archived", "C0"):
                    frappe.throw("Calling Team can only move leads to C1, C2, C6, C7, or Archived")
        if old_status in ALLOWED_TRANSITIONS:
            if new_status not in ALLOWED_TRANSITIONS.get(old_status, set()):
                frappe.throw(f"Cannot move from {old_status} to {new_status}")

old_doc = doc.get_doc_before_save()
old_status = old_doc.status if old_doc else None
new_status = doc.status

if old_status and old_status != new_status:
    if old_status in ("C0", "Cold") and new_status not in ("C0", "Cold"):
        frappe.enqueue(
            "crm.api.call_log.cancel_retry_log",
            lead_name=doc.name,
            permanent=True,
        )

    if new_status == "C1" and doc.email:
        frappe.enqueue(
            "crm.integrations.brevo.api.enroll_in_sequence",
            email=doc.email,
            lead_name=doc.name,
        )

if (
    doc.status == "No Answer"
    and doc.reference_doctype == "CRM Lead"
    and doc.reference_docname
):
    try:
        lead_status = frappe.db.get_value("CRM Lead", doc.reference_docname, "status")
        if lead_status in ("C0", "Cold"):
            frappe.enqueue(
                "crm.api.call_log.register_no_answer",
                lead_name=doc.reference_docname,
            )
    except Exception:
        frappe.log_error(frappe.get_traceback(), "No Answer Retry Trigger Failed")

from frappe.utils import today, add_days

RETRY_SEQUENCE = {1: (2,1), 2: (3,1), 3: (5,2), 5: (7,2), 7: (12,5), 12: (None,None)}

logs = frappe.get_all(
    "CRM Retry Log",
    filters={"status": "Active", "next_attempt_date": ["<=", today()]},
    fields=["name", "lead", "day_in_sequence", "attempt_count"],
)

for log in logs:
    lead_status = frappe.db.get_value("CRM Lead", log.lead, "status")
    if not lead_status or lead_status not in ("C0", "Cold"):
        frappe.db.set_value("CRM Retry Log", log.name, {
            "status": "Cancelled",
            "next_attempt_date": None,
        })
        continue

    frappe.enqueue(
        "crm.api.retry_engine.send_retry_whatsapp",
        lead_name=log.lead,
        day=log.day_in_sequence,
    )

    old_day = log.day_in_sequence
    next_day, offset = RETRY_SEQUENCE.get(old_day, (None, None))
    if next_day:
        frappe.db.set_value("CRM Retry Log", log.name, {
            "attempt_count": log.attempt_count + 1,
            "last_attempt_date": today(),
            "day_in_sequence": next_day,
            "next_attempt_date": add_days(today(), offset),
        })
    else:
        frappe.db.set_value("CRM Retry Log", log.name, {
            "attempt_count": log.attempt_count + 1,
            "status": "Exhausted",
            "next_attempt_date": None,
        })
        lead_doc = frappe.get_doc("CRM Lead", log.lead)
        lead_doc.status = "Cold"
        lead_doc.save(ignore_permissions=True)
